package com.lms.util;import java.io.*;import java.nio.file.*;import org.springframework.web.multipart.MultipartFile;public class FileUploadUtil{public static String save(String dir, MultipartFile file)throws IOException{Files.createDirectories(Paths.get(dir));String name=System.currentTimeMillis()+"_"+file.getOriginalFilename();Path path=Paths.get(dir,name);Files.copy(file.getInputStream(),path,StandardCopyOption.REPLACE_EXISTING);return path.toString();}}